"""Pydantic schemas for AI provider input/output."""

from pydantic import BaseModel, Field


class GeneratedSolution(BaseModel):
    """Structured solution generated by AI solver."""

    problem_understanding: str = Field(
        description="Clear breakdown of problem requirements, input/output specifications, and constraints."
    )
    algorithm: str = Field(
        description="Name and classification of the chosen algorithmic technique (e.g., Two Pointers, Monotonic Stack, Dynamic Programming)."
    )
    intuition: str = Field(
        description="Mathematical and logical explanation of why this algorithmic approach is optimal."
    )
    python_code: str = Field(
        description="Complete, executable, idiomatic Python 3 solution adhering strictly to platform requirements."
    )
    time_complexity: str = Field(description="Big-O time complexity analysis with justification.")
    space_complexity: str = Field(
        description="Big-O auxiliary space complexity analysis with justification."
    )
    edge_cases: list[str] = Field(
        default_factory=list,
        description="List of critical edge cases identified (e.g. empty input, single element, negative numbers, overflow limits).",
    )
    assumptions: list[str] = Field(
        default_factory=list,
        description="Explicit assumptions made about inputs or problem boundaries.",
    )


class SolutionReview(BaseModel):
    """Independent review of a generated solution."""

    is_correct: bool = Field(
        description="Whether the solution is logically and algorithmically correct."
    )
    correctness_assessment: str = Field(
        description="Detailed verification of correctness across typical and edge cases."
    )
    identified_bugs: list[str] = Field(
        default_factory=list,
        description="List of detected bugs, logical flaws, off-by-one errors, or unhandled edge cases.",
    )
    complexity_assessment: str = Field(
        description="Evaluation of whether time/space complexity will comfortably pass platform limits."
    )
    tle_risks: list[str] = Field(
        default_factory=list,
        description="Specific inputs or constraints that might trigger Time Limit Exceeded.",
    )
    memory_risks: list[str] = Field(
        default_factory=list,
        description="Specific inputs or constraints that might trigger Memory Limit Exceeded.",
    )
    recommendations: list[str] = Field(
        default_factory=list, description="Concrete improvements or code optimizations."
    )


class DiagnosticReport(BaseModel):
    """Diagnostic report and correction generated following a test failure."""

    error_summary: str = Field(
        description="Concise summary of the test failure, runtime error, or unexpected output."
    )
    failing_test_analysis: str = Field(
        description="Step-by-step trace showing why the code failed on the specific test input."
    )
    root_cause: str = Field(
        description="Fundamental reason for the bug (e.g. integer overflow, missing base case, incorrect indexing)."
    )
    suggested_fix: str = Field(description="Clear explanation of the fix applied.")
    corrected_code: str = Field(description="Complete, corrected Python 3 source code.")
